import{_ as t,o as a,c as o,a4 as d}from"./chunks/framework.DpieW3qv.js";const p=JSON.parse('{"title":"User Guide","description":"","frontmatter":{"title":"User Guide"},"headers":[],"relativePath":"guides/user-guide.md","filePath":"guides/user-guide.md","lastUpdated":null}'),s={name:"guides/user-guide.md"};function i(r,e,n,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="user-guide" tabindex="-1">User Guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User Guide&quot;">​</a></h1><p>One place for web producers: what to do every day and what to do when something goes wrong.</p><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><ul><li>Web producers and eCommerce managers who run the daily workflow</li><li>Anyone who uses <code>make pull</code>, <code>make build</code>, <code>make push</code>, and related commands</li></ul><p>You don&#39;t need to edit code or config in normal use—just follow the steps below.</p><hr><h2 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1. Introduction&quot;">​</a></h2><h3 id="what-this-tool-does" tabindex="-1">What this tool does <a class="header-anchor" href="#what-this-tool-does" aria-label="Permalink to &quot;What this tool does&quot;">​</a></h3><p>Takes campaign data from Smartsheet or Excel, turns it into HTML, validates it, and syncs it to SFCC staging. You pick a date, build it, preview it, push it, then generate the changeout email and commit.</p><h3 id="your-typical-day" tabindex="-1">Your typical day <a class="header-anchor" href="#your-typical-day" aria-label="Permalink to &quot;Your typical day&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # Sync + fetch + pick your date</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # Generate HTML for that date</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # Review in browser (optional)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # Validate + sync to SFCC staging</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> done</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # Generate changeout email</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # Save to Git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="_2-before-you-start" tabindex="-1">2. Before you start <a class="header-anchor" href="#_2-before-you-start" aria-label="Permalink to &quot;2. Before you start&quot;">​</a></h2><ul><li><strong>First time?</strong> See <a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a> and <a href="/ocapi-docs.github.io/guides/env-and-auth.html">Environment Setup</a>.</li><li><strong>First successful run:</strong> <a href="/ocapi-docs.github.io/guides/quick-start.html#from-zero-to-preview">Quick Start — From zero to preview</a> has the exact steps and what to expect.</li></ul><hr><h2 id="_3-daily-workflow" tabindex="-1">3. Daily workflow <a class="header-anchor" href="#_3-daily-workflow" aria-label="Permalink to &quot;3. Daily workflow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td>1</td><td><code>make pull</code></td><td>Git sync + fetch data + status + pick your working date (sticky)</td></tr><tr><td>2</td><td><code>make build</code></td><td>Generate HTML and OCAPI payload for that date</td></tr><tr><td>3</td><td><code>make preview</code></td><td>Show preview links to open in browser</td></tr><tr><td>4</td><td><code>make push</code></td><td>Run data quality checks, then sync to SFCC staging</td></tr><tr><td>5</td><td><code>make replicate</code></td><td>Use the STG → POD checklist</td></tr><tr><td>6</td><td><code>make done</code></td><td>Generate the changeout email</td></tr><tr><td>7</td><td><code>make commit</code></td><td>Save your refresh to Git (then run <code>git push</code> to share)</td></tr></tbody></table><p>For full step-by-step and example output, see <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Guide</a>.</p><hr><h2 id="_4-switching-dates-and-refreshes" tabindex="-1">4. Switching dates and refreshes <a class="header-anchor" href="#_4-switching-dates-and-refreshes" aria-label="Permalink to &quot;4. Switching dates and refreshes&quot;">​</a></h2><ul><li><strong>Interactive:</strong> Run <code>make select</code> and use the arrow-key picker.</li><li><strong>Direct:</strong> <code>make select DATE=2026-02-14</code> or <code>make select DATE=2026-02-14/r2</code>.</li><li><strong>Override for one command:</strong> Use <code>DATE=</code> without changing your sticky selection, e.g. <code>make preview DATE=2026-02-10</code>.</li></ul><p>When a date has multiple refreshes (r1, r2), the app will prompt you to choose, or you can set <code>REFRESH=r2</code> when needed.</p><hr><h2 id="_5-what-to-do-if" tabindex="-1">5. What to do if… <a class="header-anchor" href="#_5-what-to-do-if" aria-label="Permalink to &quot;5. What to do if…&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What to do</th></tr></thead><tbody><tr><td><strong>&quot;Already built&quot;</strong></td><td>Ready to deploy: run <code>make push</code>. Need to rebuild after template edits: run <code>make build FORCE=1</code>.</td></tr><tr><td><strong>&quot;Already synced&quot;</strong></td><td>Use the normal next steps: <code>make replicate</code>, then <code>make done</code>, then <code>make commit</code>. Only use <code>make push FORCE=1</code> if you must re-push (e.g. after a hotfix).</td></tr><tr><td><strong>&quot;Data quality check failed&quot;</strong></td><td>Fix the data in Excel or Smartsheet, then <code>make pull</code>, <code>make build</code>, and <code>make push</code> again.</td></tr><tr><td><strong>&quot;No refresh found&quot;</strong></td><td>Run <code>make pull</code> first to fetch data and create refreshes.</td></tr><tr><td><strong>Need to change content after building</strong></td><td>Edit the files in <code>dev-env/{brand}/refreshes/{date}/r#/</code>, then run <code>make build FORCE=1</code>. If that refresh was already synced, also run <code>make push FORCE=1</code> to re-sync.</td></tr><tr><td><strong>Another producer already built my date</strong></td><td>Run <code>make pull</code> to get their work, then <code>make select</code> to pick a different date.</td></tr><tr><td><strong>Warnings when pushing</strong></td><td>The app will ask: Cancel push or Push anyway. Fix issues in the source when possible; use &quot;Push anyway&quot; only when appropriate. In scripts you can use <code>YES=1</code> to skip the prompt (use with care).</td></tr></tbody></table><hr><h2 id="_6-quick-reference" tabindex="-1">6. Quick reference <a class="header-anchor" href="#_6-quick-reference" aria-label="Permalink to &quot;6. Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>When to use it</th></tr></thead><tbody><tr><td><code>make pull</code></td><td>Start of day; sync and fetch latest data</td></tr><tr><td><code>make select</code></td><td>Switch to another date or refresh</td></tr><tr><td><code>make build</code></td><td>Generate HTML for your selected date</td></tr><tr><td><code>make preview</code></td><td>See preview links before pushing</td></tr><tr><td><code>make push</code></td><td>Validate and sync to SFCC staging</td></tr><tr><td><code>make replicate</code></td><td>After push — STG → POD checklist</td></tr><tr><td><code>make done</code></td><td>Generate changeout email (after push)</td></tr><tr><td><code>make commit</code></td><td>Save your work to Git</td></tr></tbody></table><hr><h2 id="_7-need-more-help" tabindex="-1">7. Need more help? <a class="header-anchor" href="#_7-need-more-help" aria-label="Permalink to &quot;7. Need more help?&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/troubleshooting/common-errors.html">Common Errors</a> — Error messages and how to fix them</li><li><a href="/ocapi-docs.github.io/troubleshooting/faq.html">FAQ</a> — Frequently asked questions</li><li><a href="/ocapi-docs.github.io/reference/commands.html">Commands Reference</a> — Full list of make commands and options</li><li><a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Guide</a> — Detailed daily workflow with example output</li></ul>`,31)])])}const k=t(s,[["render",i]]);export{p as __pageData,k as default};
